package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

class OptionHasValueSeparatorTest {

    @Test
    void defaultValueSeparatorIsZero_and_hasValueSeparatorReturnsFalse() throws Exception {
        Option opt = new Option("o", "description");
        // default char value is '\u0000' (0) so hasValueSeparator() should be false
        assertFalse(opt.hasValueSeparator(), "Expected no value separator by default");
    }

    @Test
    void settingPositiveValueSeparator_viaReflection_makesHasValueSeparatorReturnTrue() throws Exception {
        Option opt = new Option("o", "description");

        Field f = Option.class.getDeclaredField("valueSeparator");
        f.setAccessible(true);
        // set to a positive char (e.g., 'x' -> codepoint > 0)
        f.setChar(opt, 'x');

        assertTrue(opt.hasValueSeparator(), "Expected hasValueSeparator() to be true when valueSeparator > 0");
    }

    @Test
    void settingZeroValueSeparator_viaReflection_makesHasValueSeparatorReturnFalse() throws Exception {
        Option opt = new Option("o", "description");

        Field f = Option.class.getDeclaredField("valueSeparator");
        f.setAccessible(true);
        // explicitly set to '\0'
        f.setChar(opt, '\0');

        assertFalse(opt.hasValueSeparator(), "Expected hasValueSeparator() to be false when valueSeparator == 0");
    }
}

